import os
import json
import numpy as np
import pandas as pd
from sklearn.cluster import KMeans

def generate_cluster_summary():
    os.makedirs("examples_output", exist_ok=True)
    
    # Read the canonical projections generated by src/visualization.py
    with open("artifacts/latent_projections.json", "r") as f:
        projections = json.load(f)

    # Save a mirror copy to examples_output for frontend / report consumers
    with open("examples_output/latent_projections.json", "w") as f:
        json.dump(projections, f, indent=2)

    df = pd.DataFrame(projections)
    coords = df[["umap_x", "umap_y"]].to_numpy()

    kmeans = KMeans(n_clusters=4, random_state=42, n_init=10)
    df["cluster"] = kmeans.fit_predict(coords)

    summary = []
    for c in sorted(df["cluster"].unique()):
        sub = df[df["cluster"] == c]
        total = len(sub)
        frauds = int(sub["true_label"].sum())
        uncertain = int(sub["is_uncertain"].sum())
        summary.append({
            "cluster_id": c,
            "total_transactions": total,
            "fraud_count": frauds,
            "fraud_prevalence_pct": round(float(frauds / total * 100), 2),
            "uncertainty_count": uncertain,
            "avg_fraud_probability": round(float(sub["fraud_probability"].mean()), 4)
        })

    summary_df = pd.DataFrame(summary)
    summary_df.to_csv("examples_output/clusters_summary.csv", index=False)
    print("\n[Clusters] Generated examples_output/clusters_summary.csv:")
    print(summary_df.to_string(index=False))

if __name__ == "__main__":
    generate_cluster_summary()
